-- Enterprise master data, counterparties, payroll, GL and inventory.
create table if not exists public.business_partners (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),partner_code text not null,legal_name text not null,display_name text,partner_type text not null check(partner_type in ('SUPPLIER','SUBCONTRACTOR','CONSULTANT','CONTRACTOR','CUSTOMER','LANDOWNER','BANK','GOVERNMENT','OTHER')),tax_id text,phone text,email text,address text,contact_person text,payment_terms_days integer not null default 0,bank_details jsonb not null default '{}',rating numeric,status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','BLOCKED')),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,partner_code));
create table if not exists public.project_partners (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.property_projects(id) on delete cascade,partner_id uuid not null references public.business_partners(id),role text not null check(role in ('DEVELOPER','SUPPLIER','SUBCONTRACTOR','MAIN_CONTRACTOR','CONSULTANT','LANDOWNER','SALES_AGENT','BANK','OTHER')),contract_id uuid references public.contracts(id) on delete set null,scope_description text,start_date date,end_date date,status text not null default 'ACTIVE',created_at timestamptz not null default now(),unique(project_id,partner_id,role));
create table if not exists public.customers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),partner_id uuid references public.business_partners(id) on delete set null,customer_code text not null,full_name text not null,id_type text,id_number text,phone text,email text,address text,occupation text,customer_source text,status text not null default 'LEAD',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,customer_code));
create table if not exists public.sales_reservations (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.property_projects(id),unit_id uuid references public.project_units(id) on delete set null,customer_id uuid not null references public.customers(id),reservation_no text not null,reservation_date date not null default current_date,booking_fee numeric not null default 0,selling_price numeric not null default 0,status text not null default 'RESERVED',sales_person_id uuid references public.profiles(id) on delete set null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,reservation_no));
create table if not exists public.employees (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),profile_id uuid references public.profiles(id) on delete set null,employee_no text not null,full_name text not null,department_id uuid references public.departments(id) on delete set null,job_title text,employment_type text not null default 'PERMANENT',join_date date,end_date date,tax_status text,bank_account jsonb not null default '{}',salary_base numeric not null default 0,status text not null default 'ACTIVE',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,employee_no));
create table if not exists public.payroll_runs (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),period_start date not null,period_end date not null,payment_date date,status text not null default 'DRAFT',total_gross numeric not null default 0,total_deductions numeric not null default 0,total_net numeric not null default 0,created_at timestamptz not null default now(),unique(organization_id,period_start,period_end));
create table if not exists public.payroll_items (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),payroll_run_id uuid not null references public.payroll_runs(id) on delete cascade,employee_id uuid not null references public.employees(id),gross_pay numeric not null default 0,allowances numeric not null default 0,overtime numeric not null default 0,deductions numeric not null default 0,tax numeric not null default 0,other_deductions numeric not null default 0,net_pay numeric not null default 0,breakdown jsonb not null default '{}',unique(payroll_run_id,employee_id));
create table if not exists public.chart_of_accounts (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),account_code text not null,account_name text not null,account_type text not null check(account_type in ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')),parent_id uuid references public.chart_of_accounts(id),normal_balance text not null check(normal_balance in ('DEBIT','CREDIT')),project_controlled boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,account_code));
create table if not exists public.journal_entries (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id) on delete set null,entry_no text not null,entry_date date not null default current_date,source_module text,reference_no text,description text,status text not null default 'DRAFT',posted_at timestamptz,posted_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(organization_id,entry_no));
create table if not exists public.journal_lines (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),journal_entry_id uuid not null references public.journal_entries(id) on delete cascade,account_id uuid not null references public.chart_of_accounts(id),project_id uuid references public.property_projects(id) on delete set null,description text,debit numeric not null default 0,credit numeric not null default 0,cost_center text,created_at timestamptz not null default now(),check((debit=0 and credit>0) or (credit=0 and debit>0)));
create table if not exists public.inventory_items (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),item_code text not null,item_name text not null,category text not null,unit_of_measure text not null,item_type text not null default 'MATERIAL',min_stock numeric not null default 0,max_stock numeric,standard_cost numeric not null default 0,active boolean not null default true,attributes jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,item_code));
create table if not exists public.warehouses (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid references public.property_projects(id) on delete set null,warehouse_code text not null,warehouse_name text not null,location text,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,warehouse_code));
create table if not exists public.inventory_balances (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),warehouse_id uuid not null references public.warehouses(id) on delete cascade,item_id uuid not null references public.inventory_items(id),quantity numeric not null default 0,reserved_quantity numeric not null default 0,average_cost numeric not null default 0,updated_at timestamptz not null default now(),unique(warehouse_id,item_id));
create table if not exists public.inventory_transactions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),warehouse_id uuid not null references public.warehouses(id),item_id uuid not null references public.inventory_items(id),project_id uuid references public.property_projects(id) on delete set null,transaction_type text not null,quantity numeric not null check(quantity>0),unit_cost numeric not null default 0,reference_no text,transaction_date date not null default current_date,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.master_data_catalogs (id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,catalog_key text not null,catalog_name text not null,description text,system_managed boolean not null default false,active boolean not null default true,unique(organization_id,catalog_key));
create table if not exists public.master_data_values (id uuid primary key default gen_random_uuid(),catalog_id uuid not null references public.master_data_catalogs(id) on delete cascade,value_code text not null,value_label text not null,sort_order integer not null default 0,metadata jsonb not null default '{}',active boolean not null default true,unique(catalog_id,value_code));
create index if not exists idx_project_partners_project on public.project_partners(project_id); create index if not exists idx_project_partners_partner on public.project_partners(partner_id); create index if not exists idx_sales_reservations_project on public.sales_reservations(project_id,status); create index if not exists idx_sales_reservations_customer on public.sales_reservations(customer_id); create index if not exists idx_employees_department on public.employees(department_id); create index if not exists idx_payroll_items_employee on public.payroll_items(employee_id); create index if not exists idx_journal_entries_project_date on public.journal_entries(project_id,entry_date); create index if not exists idx_journal_lines_account on public.journal_lines(account_id); create index if not exists idx_journal_lines_project on public.journal_lines(project_id); create index if not exists idx_inventory_transactions_item_date on public.inventory_transactions(item_id,transaction_date); create index if not exists idx_inventory_transactions_project on public.inventory_transactions(project_id); create index if not exists idx_inventory_balances_item on public.inventory_balances(item_id);
create or replace function public.enterprise_can_manage() returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.active and p.role in ('SUPER_ADMIN','DIRECTOR','EXECUTIVE','DEPARTMENT_HEAD','MANAGER') and p.organization_id=(select public.current_organization_id())) $$;
do $$ declare t text; begin foreach t in array array['business_partners','project_partners','customers','sales_reservations','employees','payroll_runs','payroll_items','chart_of_accounts','journal_entries','journal_lines','inventory_items','warehouses','inventory_balances','inventory_transactions','master_data_catalogs'] loop execute format('alter table public.%I enable row level security',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy %I_org_select on public.%I for select to authenticated using (organization_id=(select public.current_organization_id()))',t,t); execute format('create policy %I_manage on public.%I for all to authenticated using (organization_id=(select public.current_organization_id()) and (select public.enterprise_can_manage())) with check (organization_id=(select public.current_organization_id()) and (select public.enterprise_can_manage()))',t,t); end loop; end $$;
alter table public.master_data_values enable row level security; grant select,insert,update,delete on public.master_data_values to authenticated; create policy master_data_values_org_select on public.master_data_values for select to authenticated using (exists(select 1 from public.master_data_catalogs c where c.id=catalog_id and (c.organization_id is null or c.organization_id=(select public.current_organization_id())))); create policy master_data_values_manage on public.master_data_values for all to authenticated using ((select public.enterprise_can_manage()) and exists(select 1 from public.master_data_catalogs c where c.id=catalog_id and (c.organization_id is null or c.organization_id=(select public.current_organization_id())))) with check ((select public.enterprise_can_manage()) and exists(select 1 from public.master_data_catalogs c where c.id=catalog_id and (c.organization_id is null or c.organization_id=(select public.current_organization_id()))));
insert into public.master_data_catalogs(organization_id,catalog_key,catalog_name,description,system_managed) values(null,'PROJECT_TYPE','Jenis Proyek','Pilihan jenis proyek',true),(null,'INVENTORY_CATEGORY','Kategori Inventori','Kategori material/peralatan',true),(null,'UOM','Satuan','Satuan kuantitas',true),(null,'PARTNER_ROLE','Peran Mitra','Peran supplier/subkontraktor',true),(null,'PAYROLL_COMPONENT','Komponen Payroll','Pendapatan dan potongan',true),(null,'CUSTOMER_SOURCE','Sumber Customer','Sumber lead/customer',true),(null,'PROJECT_STATUS','Status Proyek','Lifecycle proyek',true) on conflict(organization_id,catalog_key) do nothing;
insert into public.master_data_values(catalog_id,value_code,value_label,sort_order) select c.id,x.code,x.label,x.ord from public.master_data_catalogs c cross join lateral(values('PROJECT_TYPE','RESIDENTIAL','Perumahan',1),('PROJECT_TYPE','COMMERCIAL','Komersial',2),('PROJECT_TYPE','INDUSTRIAL','Industrial',3),('PROJECT_TYPE','INFRASTRUCTURE','Infrastruktur',4),('INVENTORY_CATEGORY','CEMENT','Semen',1),('INVENTORY_CATEGORY','STEEL','Besi/Baja',2),('INVENTORY_CATEGORY','SAND','Pasir',3),('INVENTORY_CATEGORY','STONE','Batu/Agregat',4),('INVENTORY_CATEGORY','FINISHING','Finishing',5),('INVENTORY_CATEGORY','ELECTRICAL','Elektrikal',6),('INVENTORY_CATEGORY','PLUMBING','Plumbing',7),('UOM','PCS','Pcs',1),('UOM','M2','m²',2),('UOM','M3','m³',3),('UOM','KG','Kg',4),('UOM','TON','Ton',5),('UOM','LITER','Liter',6),('PARTNER_ROLE','SUPPLIER','Supplier',1),('PARTNER_ROLE','SUBCONTRACTOR','Sub Contractor',2),('PARTNER_ROLE','MAIN_CONTRACTOR','Main Contractor',3),('PARTNER_ROLE','CONSULTANT','Konsultan',4),('PAYROLL_COMPONENT','BASIC','Gaji Pokok',1),('PAYROLL_COMPONENT','ALLOWANCE','Tunjangan',2),('PAYROLL_COMPONENT','OVERTIME','Lembur',3),('PAYROLL_COMPONENT','TAX','Pajak',4),('PAYROLL_COMPONENT','DEDUCTION','Potongan',5),('CUSTOMER_SOURCE','DIRECT','Direct',1),('CUSTOMER_SOURCE','DIGITAL','Digital/Website',2),('CUSTOMER_SOURCE','AGENT','Agen/Marketing',3),('CUSTOMER_SOURCE','REFERRAL','Referral',4),('PROJECT_STATUS','PLANNING','Planning',1),('PROJECT_STATUS','ACTIVE','Active',2),('PROJECT_STATUS','ON_HOLD','On Hold',3),('PROJECT_STATUS','COMPLETED','Completed',4),('PROJECT_STATUS','CANCELLED','Cancelled',5)) x(catalog_key,code,label,ord) where c.catalog_key=x.catalog_key and c.organization_id is null on conflict(catalog_id,value_code) do nothing;
